-- Somente leitura; fotografia lógica em uma única instrução. Escopo explícito de homologação.
WITH ns AS (SELECT oid,nspname FROM pg_namespace WHERE nspname IN ('auth_admin_hml','ensaio_restauracao_hml','fiscalizacao_homologacao','mandato_testes')),
tabs AS (SELECT c.*,n.nspname FROM pg_class c JOIN ns n ON n.oid=c.relnamespace WHERE c.relkind='r'),
seqs AS (SELECT c.*,n.nspname FROM pg_class c JOIN ns n ON n.oid=c.relnamespace WHERE c.relkind='S')
SELECT jsonb_build_object(
 'formato','mandato-backup-integral-hml-v1','branch','br-lively-snow-bev5ecau','criado_em',now(),
 'schemas',(SELECT jsonb_agg(format('CREATE SCHEMA %I;',nspname) ORDER BY nspname) FROM ns),
 'roles',(SELECT jsonb_agg(rolname ORDER BY rolname) FROM pg_roles WHERE rolname NOT LIKE 'pg_%'),
 'tables',(SELECT jsonb_agg(jsonb_build_object('schema',t.nspname,'nome',t.relname,'ddl',format('CREATE TABLE %I.%I (%s);',t.nspname,t.relname,(SELECT string_agg(format('%I %s%s%s',a.attname,format_type(a.atttypid,a.atttypmod),CASE WHEN a.attidentity='a' THEN ' GENERATED ALWAYS AS IDENTITY' WHEN a.attidentity='d' THEN ' GENERATED BY DEFAULT AS IDENTITY' WHEN a.attgenerated='s' THEN ' GENERATED ALWAYS AS ('||pg_get_expr(d.adbin,d.adrelid)||') STORED' WHEN d.adbin IS NOT NULL THEN ' DEFAULT '||pg_get_expr(d.adbin,d.adrelid) ELSE '' END,CASE WHEN a.attnotnull THEN ' NOT NULL' ELSE '' END),',' ORDER BY a.attnum) FROM pg_attribute a LEFT JOIN pg_attrdef d ON d.adrelid=a.attrelid AND d.adnum=a.attnum WHERE a.attrelid=t.oid AND a.attnum>0 AND NOT a.attisdropped)),
 'colunas',(SELECT jsonb_agg(attname ORDER BY attnum) FROM pg_attribute WHERE attrelid=t.oid AND attnum>0 AND NOT attisdropped AND attgenerated=''),
 'dados_xml',query_to_xml(format('SELECT coalesce(jsonb_agg(to_jsonb(t)),''[]''::jsonb)::text AS dados FROM %I.%I t',t.nspname,t.relname),true,false,''),
 'rls',t.relrowsecurity,'force_rls',t.relforcerowsecurity) ORDER BY t.nspname,t.relname) FROM tabs t),
 'sequences',(SELECT jsonb_agg(jsonb_build_object('schema',s.nspname,'nome',s.relname,'identidade',EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_class'::regclass AND d.objid=s.oid AND d.deptype='i'),
 'ddl',format('CREATE SEQUENCE %I.%I AS %s INCREMENT %s MINVALUE %s MAXVALUE %s START %s CACHE %s %s;',s.nspname,s.relname,format_type(q.seqtypid,NULL),q.seqincrement,q.seqmin,q.seqmax,q.seqstart,q.seqcache,CASE WHEN q.seqcycle THEN 'CYCLE' ELSE 'NO CYCLE' END),
 'estado_xml',query_to_xml(format('SELECT jsonb_build_object(''valor'',last_value::text,''chamada'',is_called)::text AS estado FROM %I.%I',s.nspname,s.relname),true,false,'')) ORDER BY s.nspname,s.relname) FROM seqs s JOIN pg_sequence q ON q.seqrelid=s.oid),
 'constraints',(SELECT jsonb_agg(format('ALTER TABLE %I.%I ADD CONSTRAINT %I %s;',t.nspname,t.relname,k.conname,pg_get_constraintdef(k.oid)) ORDER BY CASE WHEN k.contype='f' THEN 1 ELSE 0 END,k.oid) FROM pg_constraint k JOIN tabs t ON t.oid=k.conrelid WHERE k.contype IN ('p','u','c','f','x')),
 'indexes',(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid)||';' ORDER BY i.indexrelid) FROM pg_index i JOIN tabs t ON t.oid=i.indrelid WHERE NOT EXISTS(SELECT 1 FROM pg_constraint k WHERE k.conindid=i.indexrelid)),
 'functions',(SELECT jsonb_agg(pg_get_functiondef(p.oid) ORDER BY p.oid) FROM pg_proc p JOIN ns n ON n.oid=p.pronamespace WHERE p.prokind IN ('f','p')),
 'triggers',(SELECT jsonb_agg(pg_get_triggerdef(g.oid)||';' ORDER BY g.oid) FROM pg_trigger g JOIN tabs t ON t.oid=g.tgrelid WHERE NOT g.tgisinternal),
 'policies',(SELECT jsonb_agg(format('CREATE POLICY %I ON %I.%I AS %s FOR %s TO %s%s%s;',p.polname,t.nspname,t.relname,CASE WHEN p.polpermissive THEN 'PERMISSIVE' ELSE 'RESTRICTIVE' END,CASE p.polcmd WHEN 'r' THEN 'SELECT' WHEN 'a' THEN 'INSERT' WHEN 'w' THEN 'UPDATE' WHEN 'd' THEN 'DELETE' ELSE 'ALL' END,(SELECT string_agg(CASE WHEN roleid=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(roleid)) END,',') FROM unnest(p.polroles) roleid),CASE WHEN p.polqual IS NOT NULL THEN ' USING ('||pg_get_expr(p.polqual,p.polrelid)||')' ELSE '' END,CASE WHEN p.polwithcheck IS NOT NULL THEN ' WITH CHECK ('||pg_get_expr(p.polwithcheck,p.polrelid)||')' ELSE '' END) ORDER BY p.oid) FROM pg_policy p JOIN tabs t ON t.oid=p.polrelid),
 'grants',(SELECT jsonb_agg(cmd) FROM (
 SELECT format('GRANT %s ON TABLE %I.%I TO %s%s;',a.privilege_type,t.nspname,t.relname,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END,CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END) AS cmd FROM tabs t CROSS JOIN LATERAL aclexplode(coalesce(t.relacl,acldefault('r',t.relowner))) a
 UNION ALL SELECT format('GRANT %s ON SEQUENCE %I.%I TO %s%s;',a.privilege_type,s.nspname,s.relname,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END,CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END) FROM seqs s CROSS JOIN LATERAL aclexplode(coalesce(s.relacl,acldefault('S',s.relowner))) a
 UNION ALL SELECT format('GRANT %s ON SCHEMA %I TO %s%s;',a.privilege_type,n.nspname,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END,CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END) FROM ns n JOIN pg_namespace q ON q.oid=n.oid CROSS JOIN LATERAL aclexplode(coalesce(q.nspacl,acldefault('n',q.nspowner))) a
 UNION ALL SELECT format('GRANT %s ON FUNCTION %s TO %s%s;',a.privilege_type,p.oid::regprocedure,CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END,CASE WHEN a.is_grantable THEN ' WITH GRANT OPTION' ELSE '' END) FROM pg_proc p JOIN ns n ON n.oid=p.pronamespace CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
 ) g)
) AS backup;
